class Solution {public:long long solve(int required,vector<int> people){if(!required)return 0;int size=1;while(size<=required)size<<=1;vector<int> dp(size,100),active={0};dp[0]=0;for(int person:people){int mask=person&required;if(!mask)continue;int before=active.size();for(int i=0;i<before;i++){int state=active[i],next=state|mask,cost=dp[state]+1;if(dp[next]==100)active.push_back(next);dp[next]=min(dp[next],cost);}}return dp[required]==100?-1:dp[required];}};